pub fn hs_CssSubStruct(p: &CssSubStruct, mut h: u32) -> u32 { h = hm(h, (p.x00) as u32); h = hm(h, (p.x01) as u32); h = hm(h, (p.pad02) as u32); h = hm(h, (p.x03) as u32); for i0 in 0..2 { h = hm(h, (p.pad04[i0]) as u32); } h = hm(h, (p.stage_id) as i32 as u32); for i0 in 0..12 { h = hm(h, (p.pad08[i0]) as u32); } for i0 in 0..4 { h = hs_PlayerInitData(&p.saved_players[i0], h); } h = hm(h, (unsafe { core::ptr::read(&p.gobj as *const _ as *const usize) } != 0) as u32); for i0 in 0..39 { h = hm(h, (unsafe { core::ptr::read(&p.jobjs[i0] as *const _ as *const usize) } != 0) as u32); } for i0 in 0..39 { h = hm(h, (p.anim_frames[i0]) as i32 as u32); } for i0 in 0..7 { h = hm(h, (p.menu_values[i0]) as i32 as u32); } h = hm(h, (unsafe { core::ptr::read(&p.text as *const _ as *const usize) } != 0) as u32); for i0 in 0..4 { h = hm(h, (p.pad200[i0]) as u32); } h }
pub fn fl_CssSubStruct(p: &mut CssSubStruct) { p.x00 = rnd() as _; p.x01 = rnd() as _; p.pad02 = rnd() as _; p.x03 = rnd() as _; for i0 in 0..2 { p.pad04[i0] = rnd() as _; } p.stage_id = rnd() as _; for i0 in 0..12 { p.pad08[i0] = rnd() as _; } for i0 in 0..4 { fl_PlayerInitData(&mut p.saved_players[i0]); } for i0 in 0..39 { p.anim_frames[i0] = rnd() as _; } for i0 in 0..7 { p.menu_values[i0] = rnd() as _; } for i0 in 0..4 { p.pad200[i0] = rnd() as _; } }
